package com.lsing.timego.ui.common

import com.lsing.timego.data.MuscleGroup

/** One shape from the traced anatomy reference art. [pathData] is a self-contained absolute SVG
 *  path string (M + relative commands, source transform baked in). [muscleGroup] is null for the
 *  base silhouette outline ([isOutline] true) and small neutral detail shapes (face, hands, feet)
 *  that carry no muscle-group meaning. [lightness] is the shape's original shading lightness
 *  (0..1, rescaled from the source artwork's near-white shading band into a visible mid-tone
 *  band) -- recoloring a tinted path with [recolorByLightness] using this value is what preserves
 *  the source art's light/shadow muscle definition instead of flattening a whole muscle group to
 *  one flat color. See docs/superpowers/specs for how this was traced and classified. */
data class MusclePathSpec(
    val pathData: String,
    val muscleGroup: MuscleGroup?,
    val isOutline: Boolean,
    val lightness: Float,
)

